import { Injectable } from '@angular/core';
import { CanActivate, Router, ActivatedRouteSnapshot } from '@angular/router';
import { AppInfoService } from './app-info.service';
import notify from 'devextreme/ui/notify';

@Injectable()
export class AuthService {
  loggedIn = true;
  constructor(private router: Router, private AppInfo: AppInfoService) {
  }
  get currentUser():CurrentUserModel {
    return this.AppInfo?.currentUserInfo;
  }
  logIn(login: string, passord: string) {
    this.loggedIn = true;
    (window as any).__AppInfo_currentUserInfo = this.currentUser;
    this.router.navigate(['/']);
  }

  logOut() {
    this.loggedIn = false;
    this.router.navigate(['/login-form']);
  }

  get isLoggedIn() {
    return this.loggedIn;
  }
  public isGranted(permissionCode: string): boolean {
    const isGranted = this.isGrantedPermission(permissionCode);
    if (!isGranted) {
      notify(`Khong co quyen [${permissionCode}]`, 'warning', 2000);
      return false;
    }
    return isGranted;
  }
  public isGrantedPermission(permissionCode: string): boolean {
    const permissionItem = this.currentUser?.permissions?.find(x => x.code == permissionCode);
    (window as any).__allPermission = (window as any).__allPermission || {}
    const __allPermission = (window as any).__allPermission;
    __allPermission[permissionCode] = permissionItem;
    return !!permissionItem
  }
  public fnRunWithPermission(permissionCode: string, fn: Function): Function {
    return () => this.runWithPermission(permissionCode, fn)
  }
  public runWithPermission(permissionCode: string, fn: Function): void {
    const isGranted = this.isGrantedPermission(permissionCode);
    if (!isGranted) {
      notify(`Khong co quyen [${permissionCode}]`, 'warning', 2000);
      return;
    }
    fn();
  }
}

@Injectable()
export class AuthGuardService implements CanActivate {
  constructor(private router: Router, private authService: AuthService) { }

  canActivate(route: ActivatedRouteSnapshot): boolean {
    const isLoggedIn = this.authService.isLoggedIn;
    const isLoginForm = route.routeConfig.path === 'login-form';

    if (isLoggedIn && isLoginForm) {
      this.router.navigate(['/']);
      return false;
    }

    if (!isLoggedIn && !isLoginForm) {
      this.router.navigate(['/login-form']);
    }

    return isLoggedIn || isLoginForm;
  }
}

export interface CurrentUserModel {
  userId: string;
  userName: string;
  fullName: string;
  email: string;
  permissions: PermissionModel[];
}
export interface PermissionModel {
  code: string;
  displayName?: string
}
