import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { DetailApiResponse } from 'src/app/pages/change-request-basic/change-request-basic.model';
import { ApiGatewayService } from 'src/app/shared/services/api-gateway.service';

export interface AppScriptApiResponse<T> {
  data: T
}

@Injectable({ providedIn: 'root' })
export class AppScriptApiService {
  constructor(private api: ApiGatewayService) {}

  /** wrap đúng cái bạn cần */
  call$<T>(
    functionName: string,
    payload: any,
  ): Observable<T> {
    return this.api.call$<any>(functionName, payload, { timeoutMs: 30000 }).pipe(
      map((res) => {
        // Tuỳ response backend của bạn, chỉnh mapping tại đây
        return res;
      })
    );
  }

  /** nếu muốn dùng async/await */
  async callAsync<T>(
    functionName: string,
    payload: any,
  ): Promise<T> {
    const res = await this.api.callAsync<any>(functionName, payload);
    // Tuỳ response backend của bạn, chỉnh mapping tại đây
    return res;
  }

  getPrepareDataForChangeRequest$(payload: {
      contextKey, recordId, changeRequestId,
    }){
    return this.call$<AppScriptApiResponse<DetailApiResponse>>('Rpc.rpc_getPrepareDataForChangeRequest', payload);
  }
}
