/* eslint-disable @angular-eslint/no-output-on-prefix */
declare const window: any;

import { Component, EventEmitter, Inject, Input, LOCALE_ID, OnChanges, OnDestroy, Output, SimpleChanges, ViewChild } from '@angular/core';
import { debounceTime, distinctUntilChanged, filter, map, switchMap, take, takeUntil, tap } from 'rxjs/operators';
import {
  ChangeRequestBasicModel,
  DetailApiResponse,
  PopupOpenContext, FormMode,
  AdditionPopupMode,
  OnPopupSaveEventModel,
  ChangeRequestBasicStatusChangesModel
} from '../change-request-basic.model';
import { AuthService, HelperService, LoadingService, LookupService } from 'src/app/shared/services';
import { BehaviorSubject, combineLatest, of, Subject } from 'rxjs';
import { AppScriptApiResponse, AppScriptApiService } from 'src/app/shared/services/app-script-api.service';
import { DyanmicFormComponent } from 'src/app/shared/components';
import { DxPopupComponent } from 'devextreme-angular/ui/popup';
import { DxFormComponent, DxTabPanelComponent } from 'devextreme-angular';

@Component({
  selector: 'app-change-request-basic-popup',
  templateUrl: './change-request-basic-popup.component.html',
  styleUrls: ['change-request-basic-popup.component.scss']
})
export class ChangeRequestBasicPopupComponent implements OnChanges, OnDestroy {
  @Input() openCtx!: PopupOpenContext;
  @Input() visible = false;
  @Input() hasNewChangeRequestData = true;
  @Output() visibleChange = new EventEmitter<boolean>();
  @Output() save = new EventEmitter<{ popupData: PopupOpenContext, userChangedData: any }>();

  @ViewChild('popup', { static: false }) popup!: DxPopupComponent;
  @ViewChild('popupForm', { static: false }) popupForm: DxFormComponent;
  // @ViewChild(DxFormComponent, { static: false }) dxForm?: DxFormComponent;
  @ViewChild('detailForm') detailFormComp!: DyanmicFormComponent;
  @ViewChild('tabPanel') tabPanelComp!: DxTabPanelComponent;

  // parent form data (dxForm)
  formDataParent: PopupOpenContext = {
    popupMode: 'create',
    id: null,
    lastStatus: null,
    contextKey: null,
    objectIdsString: null,  // recordId của DETAIL (readonly; chỉ show khi detailMode=update)
    objectRowIndexsString: null,   // readonly display
    changeType: 'update',
    summary: null,
    reason: null,
    lastUpdatedStatusAt: null,
    lastUpdatedStatusBy: null,
    createdAt: null,
    createdBy: null,
  };

  // inputs extracted
  detailMode: FormMode = 'update';
  parentMode: FormMode = 'create';
  parentId?: string | number;
  summaryString?: string;
  // state
  detailDraft: any | null = null;
  userChange_detailDraft: any = {};
  originalData: any | null = null;
  formItems: any[] = [];
  isMobile = window.innerWidth <= 768;
  contextKeys$ = this.lookupService.contextKeys.asObservable();
  // streams
  private contextKey$ = new BehaviorSubject<string>('');
  private detailMode$ = new BehaviorSubject<FormMode>('update');
  private recordId$ = new BehaviorSubject<string>(''); // chỉ dùng khi update detail
  private destroy$ = new Subject<void>();

  private silent = false;

  constructor(
    private appScriptApiService: AppScriptApiService,
    @Inject(LOCALE_ID) public ngLocale: string,
    private lookupService: LookupService,
    private loadingService: LoadingService,
    private authService: AuthService,
  ) {}
  isGrantedView(code){
    return this.authService.isGrantedPermission(code);
  }
  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
  getValue(): OnPopupSaveEventModel {
    const userChangedData = this.detailFormComp.getValue()
    const popupData = HelperService.cloneObjectInfo(this.formDataParent);
    return {
      hasNewChangeRequestData: this.hasNewChangeRequestData,
      popupMode: this.formDataParent.popupMode,
      popupData,
      userChangedData,
      originalData: this.originalData
    };
  }
  ngOnChanges(changes: SimpleChanges): void {
    if ((changes['visible'] && this.visible) || (changes['openCtx'] && this.visible)) {
      console.log('ngOnChanges', changes)
      this.bootstrap(this.openCtx);
    }
  }

  onCancelClick(): void {
    this.updateVisibility(false);
  }

  onPopupHiding(): void {
    this.updateVisibility(false);
  }

  onPopupShown(): void {
    this.refreshPopupLayout();
    setTimeout(() => {
      const editor = this.popupForm?.instance?.getEditor('changeType');
      editor?.focus();
    });
  }

  get popupTitle(): string {
    if (this.parentMode === 'create') {
      return 'Them change request basic';
    }
    const code = this.parentId;
    return code ? `Cap nhat ${code}` : 'Cap nhat change request basic';
  }

  private updateVisibility(value: boolean): void {
    this.visible = value;
    if (!value) {
      //this.popupData = {};
      this.tabPanelComp.selectedIndex = 0;
    }
    this.visibleChange.emit(value);
  }

  onReopenClick(): void {
    (this.formDataParent as any).lastStatus = 'Reopen';
  }


  bootstrap(ctx: PopupOpenContext): void {
    // cancel previous pipelines
    this.destroy$.next();

    this.detailMode = ctx.changeType;
    this.parentMode = ctx.popupMode;
    this.parentId = ctx.id;

    // reset ui state
    this.detailDraft = null;
    this.formItems = [];

    // set parent formData
    this.silentPatch(() => {
      this.formDataParent.id = ctx.id ?? null;
      this.formDataParent.lastStatus = ctx.lastStatus;
      this.formDataParent.contextKey = ctx.contextKey ?? null;
      this.formDataParent.objectIdsString = ctx.objectIdsString ?? null;
      this.formDataParent.objectRowIndexsString = null;
      this.formDataParent.changeType = ctx.changeType;
      this.formDataParent.summary = ctx.summary;
      this.formDataParent.reason = ctx.reason;
      this.formDataParent.createdAt = ctx.createdAt;
      this.formDataParent.createdBy = ctx.createdBy;
      this.formDataParent.lastUpdatedStatusAt = ctx.lastUpdatedStatusAt;
      this.formDataParent.lastUpdatedStatusBy = ctx.lastUpdatedStatusBy;
    });
    console.log('push to streams')
    // push to streams
    this.contextKey$.next(String(ctx.contextKey ?? '').trim());
    this.recordId$.next(String(ctx.objectIdsString ?? '').trim());
    this.detailMode$.next(String(ctx.changeType ?? '').trim() as FormMode);

    // logic 2: detail pipeline
    this.initDetailPipeline();
  }

  // dxForm parent change
  onParentFieldDataChanged(e: any): void {
    if (this.silent) return;

    // chỉ cho user đổi sheet context khi tạo PARENT
    if (this.parentMode === 'create') {
      if (e.dataField === 'contextKey') {
        const v = String(e.value ?? '').trim();
        this.formDataParent.contextKey = e.value;
        this.contextKey$.next(v);
      }
      if (e.dataField === 'objectIdsString') {
        const v = String(e.value ?? '').trim();
        this.formDataParent.objectIdsString = e.value;
        this.recordId$.next(v);
      }
      if (e.dataField === 'changeType') {
        const v = String(e.value ?? '').trim() as FormMode;
        this.formDataParent.changeType = e.value;
        this.detailMode = v;
        this.detailMode$.next(v);
      }

    }

    // recordId của detail: readonly theo requirement -> không next từ UI
  }

  // form child patch
  onDetailPatch(formDetailData): void {
    this.userChange_detailDraft = HelperService.cloneObjectInfo(formDetailData);
    this.summaryString = HelperService.buildChangeSummary(this.originalData, this.userChange_detailDraft);
    if(this.formDataParent && this.formDataParent?.summary !== this.summaryString){
      this.formDataParent.summary = this.summaryString;
    }
  }


  private initDetailPipeline(): void {
    console.log('initDetailPipeline')
    this.detailMode$.pipe().subscribe(res => {
      if (res === 'create') {
        this.formDataParent.objectIdsString = null;
      }
    });
    combineLatest([this.contextKey$, this.recordId$]).pipe(
      debounceTime(150),
      map(([sidname, rid]) => ({
        sidname: (sidname || '').trim(),
        rid: (rid || '').trim(),
        valid: ((this.detailMode === 'update' || this.detailMode === 'delete') && !!(sidname || '').trim() && !!(rid || '').trim()) || (this.detailMode === 'create' && !!(sidname || '').trim())
      })),
      tap(x => {
        console.log(x)
        if (!x.valid) {
          this.detailDraft = null;
          this.formItems = [];
          this.silentPatch(() => (this.formDataParent.objectRowIndexsString = null));
        }
      }),
      filter(x => x.valid),
      distinctUntilChanged((a, b) => a.sidname === b.sidname && a.rid === b.rid),
      switchMap(x =>
        this.loadingService.runWithLoading$(
          this.apiGetDetailByRecordId(x.sidname, x.rid)
        )
      ),
      takeUntil(this.destroy$)
    ).subscribe(res => {

      this.applyDetailResponse(res?.data);
    });
  }
  private applyDetailResponse(res: DetailApiResponse): void {
    console.log('applyDetailResponse', res)
    // formItems + detail luôn đến từ API
    this.formItems = HelperService.cloneObjectInfo(res?.formItems ?? []);

    // detail từ API: update => full detail; create => { rowIndex: ... }
    const originalData = HelperService.cloneObjectInfo(res?.originalData ?? {});
    const changedData = res?.changedData ? HelperService.cloneObjectInfo(res?.changedData ?? {}) : null;
    const data = changedData ? changedData : originalData;
    // Nếu create-mode: bạn muốn user fill mới => detailDraft nên là object "mở rộng" từ apiDetail
    // (giữ rowIndex từ API, các field khác rỗng)
    // Nếu update-mode: detailDraft full data từ API
    this.detailDraft = { ...(data) };
    this.originalData = HelperService.cloneObjectInfo(res?.originalData ?? {});
    // fill readonly fields trên parent form
    this.silentPatch(() => {
      this.formDataParent.objectRowIndexsString = res?.objectRowIndexsString ?? null;
      this.formDataParent.formId = res?.formId;
      // recordId parent form: update-mode thì giữ recordId input; create-mode vẫn null
      // (Nếu backend create-mode trả recordId sớm thì bạn có thể set ở đây nếu muốn)
    });

    if (this.visible && this.formItems) this.refreshPopupLayout();
  }
  private refreshPopupLayout(): void {
    // đợi DOM render xong rồi mới đo lại
    console.log('refreshPopupLayout')
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        //this.popup?.instance?.repaint();
      });
    });
  }
  private silentPatch(fn: () => void): void {
    this.silent = true;
    try { fn(); }
    finally { setTimeout(() => (this.silent = false), 0); }
  }

  // ====== STUB APIS (replace by services) ======

  private apiGetDetailByRecordId(contextKey: string, recordId: string) {
    // should return: { ...detailFields, recordId, rowIndex, arrayFormItems: [] }
    if (!contextKey) {
      const r: AppScriptApiResponse<DetailApiResponse> = {
        data: null,
      }
      return of(r)
    }
    return this.appScriptApiService.getPrepareDataForChangeRequest$( {
      contextKey, recordId, changeRequestId: this.parentId
    })
  }

  validate() {
    return this.popupForm?.instance?.validate();
  }
  validateDetail() {
    return this.detailFormComp?.validate();
  }
  onSaveClick(): void {
    console.log(this.validate())
    if (!this.detailDraft || !this.validate().isValid || !this.validateDetail().isValid) return;
    const valueOnSave = this.getValue();
    this.save.emit(valueOnSave);


  }
}

