// lookup.service.ts
import { Injectable } from '@angular/core';
import { BaseLookupService } from './base-lookup.service';
import { LookupOption } from '../models/lookup.model';
import { FormConfig } from '../models/form-config.model';

@Injectable({ providedIn: 'root' })
export class LookupService {

  private tenantKey: string;
  hangHoas: BaseLookupService<LookupOption>;
  sanPhams: BaseLookupService<LookupOption>;
  khos: BaseLookupService<LookupOption>
  lienHes: BaseLookupService<LookupOption>;
  khachHangs: BaseLookupService<LookupOption>;
  dvVanChuyens: BaseLookupService<LookupOption>;
  contextKeys: BaseLookupService<LookupOption>;

  constructor() {
    // tenantKey = userId + tenantId, lấy từ login
    this.tenantKey = this.getTenantKey();
    const ttlMs = 24 * 60 * 60 * 1000; // 24 hours
    this.hangHoas = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "hangHoas" }, ttlMs, this.tenantKey);
    this.sanPhams = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "sanPhams" }, ttlMs, this.tenantKey);
    this.khos = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "khos" }, ttlMs, this.tenantKey);
    this.lienHes = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "lienHes" }, ttlMs, this.tenantKey);
    this.khachHangs = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "khachHangs" }, ttlMs, this.tenantKey);
    this.dvVanChuyens = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "dvVanChuyens" }, ttlMs, this.tenantKey);
    this.contextKeys = new BaseLookupService<LookupOption>('Rpc.rpc_getLookupOptions', { contextKey: "contextKeys" }, ttlMs, this.tenantKey);

  }

  init(): void {
    // preload all lookup
    this.preloadAll();

    // watch backend version changes
    setInterval(() => {
      this.checkForBackendUpdate();
    }, 5 * 60 * 1000); // 5 phút 1 lần, tùy chỉnh
  }


  /** Clear toàn bộ lookup (logout / change tenant) */
  clearAll(): void {
    this.hangHoas.refresh();
    this.sanPhams.refresh();
    this.khos.refresh();
    this.lienHes.refresh();
    this.khachHangs.refresh();
    this.dvVanChuyens.refresh();
    this.contextKeys.refresh();
  }

  /** Preload lookup khi app start */
  preloadAll(): void {
    this.hangHoas.get().catch(() => { });
    this.sanPhams.get().catch(() => { });
    this.khos.get().catch(() => { });
    this.lienHes.get().catch(() => { });
    this.khachHangs.get().catch(() => { });
    this.dvVanChuyens.get().catch(() => { });
    this.contextKeys.get().catch(() => { });
  }
  /** --- refresh all lookup --- */
  private refreshAll(): void {
    this.clearAll();
    this.preloadAll();
  }
  /** --- check backend version change --- */
  private async checkForBackendUpdate(): Promise<void> {
    const promises = [
      this.hangHoas.get().catch(() => { }),
      this.sanPhams.get().catch(() => { }),
      this.khos.get().catch(() => { }),
      this.lienHes.get().catch(() => { }),
      this.khachHangs.get().catch(() => { }),
      this.dvVanChuyens.get().catch(() => { }),
      this.contextKeys.get().catch(() => { })
    ];

    const results = await Promise.all(promises);
    // nếu backendVersion thay đổi, BaseLookupService sẽ auto refresh
    results.forEach((res, idx) => {
      if (!res) this.refreshAll();
    });

  }


  /** --- helper multi-tenant key --- */
  private getTenantKey(): string {
    const userId = (window as any)._USER_ID ?? 'GUEST';
    const tenantId = (window as any)._TENANT_ID ?? 'GLOBAL';
    return `${userId}_${tenantId}`;
  }

}
