import { Component, HostBinding, OnDestroy } from '@angular/core';
import { AuthService, ScreenService, AppInfoService, LoadingService, LookupService } from './shared/services';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent implements OnDestroy {
  loadingVisible = false;
  private readonly subscriptions: Subscription[] = [];

  @HostBinding('class') get getClass() {
    return Object.keys(this.screen.sizes).filter(cl => this.screen.sizes[cl]).join(' ');
  }

  constructor(
    private authService: AuthService,
    private screen: ScreenService,
    public appInfo: AppInfoService,
    private loadingService: LoadingService,
    private lookupService: LookupService
  ) {
    this.subscriptions.push(
      this.loadingService.loading$.subscribe((visible) => (this.loadingVisible = visible))
    );
  }
  ngOnInit(): void {
    console.log('App init.')
    this.lookupService.clearAll();
    this.lookupService.preloadAll();
  }
  isAutorized() {
    return this.authService.isLoggedIn;
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((sub) => sub.unsubscribe());
  }
}
